    function run(uint256 a) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (a)); require(a <= 1000000000000000000000000000000);
        require(address(this).balance >= a);
        c.addToBalance{value: a}(); if (__ESBMC_reverted()) return;
        uint256 preWithdrawBalance = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 preWithdrawContractBalance = address(c).balance;
        c.withdrawBalance(); if (__ESBMC_reverted()) return;
        uint256 postBalance = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 postContractBalance = address(c).balance;
        assert(postBalance == 0 && preWithdrawContractBalance - postContractBalance == preWithdrawBalance);
