pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 a) internal {
        a = bound(a, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= a);
        try c.addToBalance{value: a}() {} catch { return; }
        uint256 preWithdrawBalance;
        try c.getBalance(address(this)) returns (uint256 __r) { preWithdrawBalance = __r; } catch { return; }
        uint256 preWithdrawContractBalance = address(c).balance;
        try c.withdrawBalance() {} catch { return; }
        uint256 postBalance;
        try c.getBalance(address(this)) returns (uint256 __r) { postBalance = __r; } catch { return; }
        uint256 postContractBalance = address(c).balance;
        assertTrue(postBalance == 0 && preWithdrawContractBalance - postContractBalance == preWithdrawBalance);
    }

    function testFuzz_run(uint256 a) public {
        _run(a);
    }

    receive() external payable {}
}
